let current='evangelion', mode='deep';
let searchTimer=0, searchController=null, recommendationController=null, recommendationCache=new Map;
let archive=[], archiveReady=false, tasteProfile={tags:[],statement:''}, similarityEdges=[], connectionGraph=[], selectedRating=5;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=value=>String(value??'').replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));
const safeUrl=value=>{try{const u=new URL(String(value),location.origin);return u.protocol==='http:'||u.protocol==='https:'?u.href:''}catch{return''}};
function renderWork(){const w=works[current],p=$('#workPoster'),poster=safeUrl(w.posterUrl);p.className='poster '+(w.poster||'poster-live');p.style.backgroundImage=poster?`linear-gradient(0deg,rgba(8,10,14,.35),rgba(8,10,14,.05)),url("${poster}")`:'';p.innerHTML=poster?`<span></span><i>${esc(w.year||'')}</i>`:`<span>${esc(w.posterText||w.title)}</span><i>${esc(w.year||'')}</i>`;$('#workType').textContent=w.type||w.mediaType;$('#workYear').textContent=w.year||'연도 미상';$('.award').textContent=w.award||w.source||'';$('#workTitle').textContent=w.title;$('#workCreator').textContent=w.creator;$('#workQuote').textContent=w.aiComment?`“${w.aiComment}”`:w.quote||`“${(w.description||'작품 설명이 아직 없습니다.').slice(0,180)}”`;const dna=w.analysis?.tags?.map(t=>t.tag)||w.tags||[];$('#tasteTags').innerHTML=(dna.length?dna:['Taste DNA 분석 전']).map(t=>`<span class="tag">#${esc(t)}</span>`).join('');const score=w.score||Math.round((w.analysis?.tags?.[0]?.score||.72)*100);$('#bridgeScore').textContent=score;$('#bridgeMeter').style.width=score+'%';$('#saveBtn').classList.toggle('saved',archive.includes(current));$('#saveBtn').innerHTML=archive.includes(current)?'<span>✓</span> 내 성좌에서 빼기':'<span>＋</span> 내 성좌에 담기';renderRecs();}
async function renderRecs(){const labels={story:'서사의 뼈대를 따라 연결했어요.',mood:'보고 난 뒤 남는 감정의 온도를 따라갑니다.',idea:'작품이 던지는 질문을 다음 매체로 이어갑니다.',visual:'색, 공간, 이미지의 리듬으로 연결했어요.',deep:'장르는 멀지만 취향의 핵심이 맞닿은 작품들입니다.'};$('#connectionIntro').textContent=labels[mode];if(recs[current]){const list=recs[current]?.[mode]||recs[current]?.deep;$('#recommendations').innerHTML=list.map(r=>`<article class="rec-card"><span class="type">${esc(r[0])}</span><span class="arrow">↗</span><h4>${esc(r[1])}</h4><span class="creator">${esc(r[2])}</span><p class="reason">“${esc(r[3])}”</p></article>`).join('');return}const selected=current,key=`${current}:${mode}`,cached=recommendationCache.get(key);if(cached){paintRecommendations(cached);return}if(recommendationController)recommendationController.abort();recommendationController=new AbortController();$('#recommendations').innerHTML='<div class="recommendation-loading">Taste DNA로 다른 매체를 탐색하고 있어요…</div>';try{const r=await fetch('/api/recommendations',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({work:{...works[current],id:current},mode}),signal:recommendationController.signal}),data=await r.json();if(!r.ok)throw new Error(data.error||'recommendations');if(selected!==current)return;recommendationCache.set(key,data.items||[]);connectionGraph=[...(data.items||[]),...connectionGraph.filter(x=>!data.items?.some(y=>y.fromWorkId===x.fromWorkId&&y.id===x.id&&y.mode===x.mode))];paintRecommendations(data.items||[])}catch(error){if(error.name==='AbortError')return;$('#recommendations').innerHTML='<div class="recommendation-loading">지금은 연결 작품을 찾지 못했습니다. 잠시 후 다시 시도해 주세요.</div>'}}
function paintRecommendations(items){items.forEach(w=>works[w.id]=w);$('#recommendations').innerHTML=items.length?items.map(w=>`<button class="rec-card rec-action" data-recommendation="${esc(w.id)}"><span class="type">${esc(w.mediaType)}</span><span class="match-score">${Math.round((w.similarity||0)*100)}% DNA</span><h4>${esc(w.title)}</h4><span class="creator">${esc(w.creator)}</span><p class="reason">“${esc(w.reason)}”</p><small>${(w.sharedTags||[]).map(t=>`#${esc(t)}`).join(' ')} · 성좌에 기록됨</small></button>`).join(''):'<div class="recommendation-loading">이 모드에서 충분히 닮은 작품을 찾지 못했습니다.</div>'}
function selectWork(id){current=id;mode='deep';$$('#modeTabs button').forEach(b=>b.classList.toggle('active',b.dataset.mode==='deep'));renderWork();$('#searchResults').hidden=true;$('#searchInput').value='';$('#workSection').scrollIntoView({behavior:'smooth',block:'start'})}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}
async function loadTasteProfile(){try{const r=await fetch('/api/taste-profile'),data=await r.json();if(r.ok){tasteProfile=data;$('#tasteStatement').textContent=data.statement}}catch{}}
async function loadSimilarities(){try{const r=await fetch('/api/taste-similarities'),data=await r.json();similarityEdges=r.ok?data.edges||[]:[]}catch{similarityEdges=[]}}
async function loadConnections(){try{const r=await fetch('/api/connections'),data=await r.json();connectionGraph=r.ok?data.items||[]:[];connectionGraph.forEach(w=>works[w.id]=w)}catch{connectionGraph=[]}}
async function loadArchive(){try{const r=await fetch('/api/archive');const data=await r.json();if(!r.ok)throw new Error(data.error||'archive');archive=data.items.map(w=>w.id);data.items.forEach(w=>works[w.id]=w);archiveReady=true;$('#archiveCount').textContent=archive.length;await Promise.all([loadTasteProfile(),loadSimilarities(),loadConnections()]);renderWork();if(!$('#archiveView').hidden)renderArchive()}catch(error){archiveReady=false;$('#archiveCount').textContent='!';toast(error.message==='로그인이 필요합니다.'?'로그인 후 아카이브를 사용할 수 있어요.':'아카이브 연결을 확인해 주세요.')}}
async function save(){if(!archiveReady){toast('아카이브를 불러오는 중입니다.');return}if(!archive.includes(current)){selectedRating=5;$('#commentInput').value='';paintRating();$('#saveDialogTitle').textContent=`${works[current].title}이 왜 좋았나요?`;$('#saveDialog').showModal();return}const button=$('#saveBtn');button.disabled=true;try{const r=await fetch(`/api/archive/${encodeURIComponent(current)}`,{method:'DELETE'}),data=await r.json();if(!r.ok)throw new Error(data.error||'delete');archive=archive.filter(id=>id!==current);delete works[current].analysis;delete works[current].aiComment;await Promise.all([loadTasteProfile(),loadSimilarities()]);toast('내 성좌에서 꺼냈어요.');$('#archiveCount').textContent=archive.length;renderWork();if(!$('#archiveView').hidden)renderArchive()}catch(error){toast(error.message||'삭제하지 못했습니다.')}finally{button.disabled=false}}
async function submitSave(){const button=$('#analyzeSaveBtn');button.disabled=true;button.textContent='Taste DNA를 읽는 중…';try{const r=await fetch('/api/archive',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({work:{...works[current],id:current},rating:selectedRating,myComment:$('#commentInput').value})}),data=await r.json();if(!r.ok)throw new Error(data.error||'save');works[current]=data.work;archive=[current,...archive.filter(id=>id!==current)];$('#archiveCount').textContent=archive.length;await Promise.all([loadTasteProfile(),loadSimilarities()]);$('#saveDialog').close();renderWork();toast('Taste DNA가 성좌에 기록됐어요.')}catch(error){toast(error.message||'분석하지 못했습니다.')}finally{button.disabled=false;button.textContent='저장하고 Taste DNA 만들기'}}
function paintRating(){$$('#ratingInput button').forEach(b=>b.classList.toggle('lit',Number(b.dataset.rating)<=selectedRating))}
function showView(view){$('#discoverView').hidden=view!=='discover';$('#archiveView').hidden=view!=='archive';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='archive')renderArchive();scrollTo({top:0,behavior:'smooth'})}
function renderArchive(){if(!archiveReady){$('#constellation').innerHTML='<p class="archive-empty">아카이브를 불러오고 있어요…</p>';return}const items=archive.filter(id=>works[id]);if(!items.length){$('#constellation').innerHTML='<p class="archive-empty">아직 저장한 작품이 없습니다.<br>탐색에서 첫 작품을 성좌에 담아보세요.</p>';$('#connectionDetail').textContent='작품이 쌓이면 서로 닮은 이유를 연결해 드립니다.';$('#dnaBars').innerHTML='<p class="archive-empty">첫 작품을 저장하면 Taste DNA가 생성됩니다.</p>';return}const positions=items.map((_,i)=>{const angle=-Math.PI/2+i*(Math.PI*2/items.length),radius=i?31:0;return[50+Math.cos(angle)*radius,52+Math.sin(angle)*radius]}),positionById=new Map(items.map((id,i)=>[id,positions[i]])),edges=similarityEdges.filter(e=>positionById.has(e.sourceId)&&positionById.has(e.targetId));let lines=edges.map(e=>{const a=positionById.get(e.sourceId),b=positionById.get(e.targetId),s=Math.max(0,Math.min(1,e.similarity));return`<line x1="${a[0]}%" y1="${a[1]}%" x2="${b[0]}%" y2="${b[1]}%" stroke="#8d93ff" stroke-opacity="${(.2+s*.7).toFixed(2)}" stroke-width="${(1+s*2).toFixed(2)}"/>`}).join('');if(!lines)for(let i=1;i<items.length;i++)lines+=`<line x1="${positions[0][0]}%" y1="${positions[0][1]}%" x2="${positions[i][0]}%" y2="${positions[i][1]}%" stroke="#555a64" stroke-width="1" stroke-dasharray="4 5"/>`;$('#constellation').innerHTML=`<svg>${lines}</svg>`+items.map((id,i)=>`<button class="star-node" style="left:${positions[i][0]}%;top:${positions[i][1]}%" data-node="${esc(id)}"><i></i>${esc(works[id].title)}</button>`).join('');$$('.star-node').forEach(n=>n.onclick=()=>{const id=n.dataset.node,w=works[id],tags=w.analysis?.tags?.slice(0,3).map(t=>t.tag).join(' / ')||'Taste DNA 분석 전',closest=similarityEdges.filter(e=>e.sourceId===id||e.targetId===id).sort((a,b)=>b.similarity-a.similarity)[0],other=closest&&(closest.sourceId===id?closest.targetId:closest.sourceId),match=other&&works[other]?`<div class="vector-match">↔ ${esc(works[other].title)} · ${Math.round(closest.similarity*100)}% 유사</div>`:'';$('#connectionDetail').innerHTML=`<strong>${esc(w.title)}</strong> — ${esc(tags)}${match}<div class="archive-review"><strong>${'★'.repeat(Math.max(0,Math.min(5,Number(w.rating)||0)))}</strong> ${esc(w.myComment||w.aiComment||'')}</div>`});const dna=tasteProfile.tags||[];$('#dnaBars').innerHTML=dna.length?dna.map(d=>`<div class="dna-row"><div class="dna-label"><span>${esc(d.tag)}</span><span>${Number(d.score)||0}</span></div><div class="dna-track"><i style="width:${Math.max(0,Math.min(100,Number(d.score)||0))}%"></i></div></div>`).join('')+`<small class="dna-engine">Taste DNA · ${similarityEdges.length}개의 유사도 선 · ${connectionGraph.length}개의 발견 연결</small>`:'<p class="archive-empty">저장한 작품을 분석하고 있어요.</p>'}
$('#modeTabs').onclick=e=>{const b=e.target.closest('button');if(!b)return;mode=b.dataset.mode;$$('#modeTabs button').forEach(x=>x.classList.toggle('active',x===b));renderRecs()};
$('#recommendations').onclick=e=>{const card=e.target.closest('[data-recommendation]');if(card)selectWork(card.dataset.recommendation)};
$$('[data-work]').forEach(b=>b.onclick=()=>selectWork(b.dataset.work));$$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('#saveBtn').onclick=save;
$('#ratingInput').onclick=e=>{const b=e.target.closest('[data-rating]');if(b){selectedRating=Number(b.dataset.rating);paintRating()}};
$('#saveForm').onsubmit=e=>{e.preventDefault();submitSave()};
$('#searchInput').oninput=e=>{const q=e.target.value.trim();clearTimeout(searchTimer);if(searchController)searchController.abort();if(q.length<2){$('#searchResults').hidden=true;return}$('#searchResults').hidden=false;$('#searchResults').innerHTML='<div class="search-message">영화·책·애니를 함께 찾고 있어요…</div>';$('#sourceStatus').className='source-status loading';searchTimer=setTimeout(async()=>{searchController=new AbortController();try{const r=await fetch(`/api/search?q=${encodeURIComponent(q)}`,{signal:searchController.signal});if(!r.ok)throw new Error('search');const data=await r.json();data.items.forEach(w=>works[w.id]=w);$('#searchResults').innerHTML=data.items.map(w=>{const poster=safeUrl(w.posterUrl);return`<button class="search-result" data-result="${esc(w.id)}"><span class="result-thumb" ${poster?`style="background-image:url('${esc(poster)}')"`:''}></span><span><strong>${esc(w.title)}<em class="provider-pill">${esc(w.source)}</em></strong><small>${esc(w.mediaType)} · ${esc(w.year||'연도 미상')} · ${esc(w.creator)}</small></span></button>`}).join('')||'<div class="search-message">검색 결과가 없습니다. 다른 제목으로 찾아보세요.</div>';const active=Object.entries(data.sources).filter(([,v])=>v==='ok').map(([k])=>k),waiting=Object.entries(data.sources).filter(([,v])=>v==='needs_key').map(([k])=>k);$('#sourceStatus').className='source-status '+(waiting.length?'partial':'');$('#sourceStatus').innerHTML=`<span class="live-dot"></span> ${esc(active.join(' · '))} 실시간 연결${waiting.length?` · ${esc(waiting.join(' · '))} 키 등록 대기`:''}`;}catch(err){if(err.name==='AbortError')return;$('#searchResults').innerHTML='<div class="search-message">검색 서비스에 잠시 연결할 수 없습니다. 다시 시도해 주세요.</div>';$('#sourceStatus').className='source-status partial';}},350)};
$('#searchResults').onclick=e=>{const b=e.target.closest('[data-result]');if(b)selectWork(b.dataset.result)};
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#searchInput').focus()}});document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))$('#searchResults').hidden=true});
